        return mesaj(r, r.pereche() == null ? null : new MWarehouse(getCtx(), r.pereche().gestiuneWms(), get_TrxName()).getValue(),
                new MWarehouse(getCtx(), gestiune, get_TrxName()).getName());
    }

    /**
     * PUR: refuzul ⇒ excepție cu textul tradus; perechea nouă ⇒ {@code t331.activare.gata} (codul lui W, rândurile de stoc);
     * existentă ⇒ {@code t331.activare.deja} (numele lui G — argumentul cheii din blocul lotului B).
     */
    public static String mesaj(PerecheWms.Rezultat r, String codW, String numeG) {
        if (r.refuz() != null)
            throw new AdempiereException(r.refuz());
        return r.noua() ? Etichete.t("t331.activare.gata", codW, r.randuriActivare()) : Etichete.t("t331.activare.deja", numeG);
    }
}
