public final class PoartaPerioada {

    /** Rând dintr-o lună în care se poate lucra. */
    public static final String STIL_DESCHIS = "background:#eafaf0";
    /** Rând dintr-o lună închisă — nu se mai poate opera pe el. */
    public static final String STIL_INCHIS  = "background:#fdecec";

    private PoartaPerioada() { }

    /** Perioada lunii datei date, pentru firma dată. 0 dacă nu există. */
    public static int idPerioada(int client, LocalDate zi) {
        if (zi == null)
            return 0;
        return DB.getSQLValue(null,
            "SELECT p.c_period_id FROM c_period p"
          + " JOIN c_year y ON y.c_year_id=p.c_year_id"
          + " JOIN c_calendar c ON c.c_calendar_id=y.c_calendar_id"
          + " WHERE c.ad_client_id=? AND p.periodtype='S'"
          + "   AND ?::date BETWEEN p.startdate::date AND p.enddate::date"
          + " ORDER BY p.c_period_id FETCH FIRST 1 ROWS ONLY",
            new Object[]{Integer.valueOf(client), Timestamp.valueOf(zi.atStartOfDay())});
    }

    /**
     * Luna datei e deschisă pentru firma dată? O lună fără perioadă definită e tratată ca
     * ÎNCHISĂ: lipsa perioadei oprește oricum postarea, iar a spune „deschisă" ar lăsa omul
     * să introducă documente care apoi nu intră în contabilitate.
     */
    public static boolean deschisa(int client, LocalDate zi) {
        int perioada = idPerioada(client, zi);
        if (perioada <= 0)
            return false;
        // T09 (R19, decizia Q-B): deschisă = 'O', oglinda MPeriodControl.isOpen(false). O lună «N» (neîncepută) sau
        // «P» nu e deschisă: motorul ar refuza documentul cu @PeriodClosed@ (MPayment.prepareIt), în engleză
        return stareDeschisa(DB.getSQLValueString(null,
            "SELECT periodstatus FROM c_periodcontrol WHERE c_period_id=? AND periodstatus='O'"
          + " FETCH FIRST 1 ROWS ONLY", perioada));
    }

    /** T09 (R19): starea unui control de perioadă permite scrierea? Doar {@code 'O'} (deschisă). */
    public static boolean stareDeschisa(String periodstatus) {
        return periodstatus != null && "O".equals(periodstatus.trim());
    }

    /**
     * T09 (R19, decizia orchestratorului — varianta B): luna e ÎNCHISĂ INTEGRAL — are perioadă și TOATE controalele ei
     * sunt {@code 'C'} (închisă) sau {@code 'P'} (închisă permanent). O lună {@code 'N'} (neîncepută) nu e nici
     * deschisă, nici închisă: nu blochează ordinea lunilor («Deblochez luna») și nu apare ca închisă.
     */
    public static boolean inchisaIntegral(int client, LocalDate zi) {
        int perioada = idPerioada(client, zi);
        return perioada > 0 && inchisaIntegral(stari(perioada));
    }

    /**
     * P01.C02.T0002 (P01.T158) L4 (12_ §3.7): controalele perioadei lunii, {închise (C / P), totale, id-ul perioadei,
     * neîncepute (N)}; {@code {-1, -1, -1, 0}} când luna n-are perioadă contabilă. Sursa comună a statusului scurt
     * («Închidere lună», «State salarii», ghidul).
     */
    public static int[] controaleLuna(int client, java.time.YearMonth luna) {
        return controaleLuna(luna == null ? 0 : idPerioada(client, luna.atEndOfMonth()), InchidereLuna::controalePerioada);
    }

    /** L4, pur: {@link #controaleLuna(int, java.time.YearMonth)} cu perioada dată și sursa controalelor injectată. */
    static int[] controaleLuna(int perioada, java.util.function.IntFunction<int[]> controale) {
        if (perioada <= 0)
            return new int[]{-1, -1, -1, 0};
        int[] n = controale.apply(perioada);   // {închise C / P, neîncepute N, totale}
        return new int[]{n[0], n[2], perioada, n[1]};
    }

    /** L4 (12_ §3.7), pur: un singur cuvânt pentru starea lunii — NEGĂSITĂ / NEÎNCEPUTĂ / DESCHISĂ / ÎNCHISĂ / parțial. */
    public static String statusScurt(int[] pc) {
        if (pc[2] <= 0)
            return com.eva.ro.contab.documente.Etichete.t("t21.inchf.per.scurt.negasita");
        if ("t03.per.neinceputa".equals(InchidereLuna.cheieStarePerioada(pc[0], pc[3], pc[1])))
            return com.eva.ro.contab.documente.Etichete.t("t03.per.scurt.neinceputa");
        if (pc[0] == 0)
            return com.eva.ro.contab.documente.Etichete.t("t21.inchf.per.scurt.deschisa");
