    static final Pattern LINIE = Pattern.compile("(\\d{1,10})/(\\d{1,10})/(\\d{1,10})=(-?\\d{1,12}(?:\\.\\d{1,12})?)");
    static final String SQL_FIRMA_GESTIUNE = "SELECT ad_client_id FROM m_warehouse WHERE m_warehouse_id=?";
