        }
    }

    /**
     * R12 (B8, intrare ostilă): liniile {@code locator/produs/asi=faptic} separate prin {@code \n}; liniile goale se sar;
     * o linie ilizibilă sau o cheie repetată ⇒ refuz {@code t163.refuz.pozitii_ilizibile} cu numărul liniei (de la 1).
     */
    public static Map<String, BigDecimal> parseazaPozitii(String text) {
        Map<String, BigDecimal> out = new LinkedHashMap<>();
        if (text == null)
            return out;
        String[] linii = text.split("\n", -1);
        for (int i = 0; i < linii.length; i++) {
            String l = linii[i].strip();
            if (l.isEmpty())
                continue;
            Matcher m = LINIE.matcher(l);
            if (!m.matches())
                throw new AdempiereException(Etichete.t("t163.refuz.pozitii_ilizibile", String.valueOf(i + 1)));
            String cheie = Integer.parseInt(m.group(1)) + "/" + Integer.parseInt(m.group(2)) + "/" + Integer.parseInt(m.group(3));
            if (out.put(cheie, new BigDecimal(m.group(4))) != null)
                throw new AdempiereException(Etichete.t("t163.refuz.pozitii_ilizibile", String.valueOf(i + 1)));
        }
        return out;
    }

    /**
