     * {@code t163.refuz.pozitii_multiple} (articolul, numărul pozițiilor; D-ORC-T163-18 a-1 — faptica unică nu se împarte).
     */
    private java.util.List<ArticoleDiverse.Pozitie> pozitiiUnice(int client, Map<String, BigDecimal> faptic, String trx) {
        java.util.List<ArticoleDiverse.Pozitie> out = new java.util.ArrayList<>();
        for (Map.Entry<String, BigDecimal> e : faptic.entrySet()) {
            java.util.List<ArticoleDiverse.Pozitie> p = InventarDiverse.pozitii(client, gestiune, Map.of(e.getKey(), e.getValue()), trx);
            String m = refuzPozitiiMultiple(p);
            if (m != null)
                throw new AdempiereException(Etichete.t(m, p.get(0).codArticol(), String.valueOf(p.size())));
            out.addAll(p);
        }
        return out;
    }

    /** Regula pură a cheii {@code 0/produs/0} (D-ORC-T163-18, RM1): ≥ 2 poziții ⇒ {@code t163.refuz.pozitii_multiple}, altfel {@code null}. */
    public static String refuzPozitiiMultiple(java.util.List<ArticoleDiverse.Pozitie> pozitiiCheie) {
        return pozitiiCheie.size() > 1 ? "t163.refuz.pozitii_multiple" : null;
    }

