"""P01.T329 (P01.C03.T0015) §9 / X213 — SQL-urile noi și cele atinse de L-A, rulate pe SCHEMA REALĂ a clonei (după migrarea jarului T329):
fiecare interogare cu parametrii `?` înlocuiți cu NULL și `LIMIT 0` (înaintea lui `FOR UPDATE`), descrisă cu `\\gdesc` (numele și tipul
coloanelor = ResultSetMetaData). Constantele se citesc din SURSA ref-ului dat (nu copiate de mână): MotorStraturi (straturile cu coloana ASI
pe ramurile FIFO / LIFO / MEDIU, `sqlLinii` pe cele 4 tabele cu coloanele 15–17, costul pe lot pe 3 trepte, instanța, subtipul, ASI-ul
stratului), LoturiArticole (setarea, setul, urmărirea, instanța) și EvaMetadata.ensureT329 (firmele cu Y, indexul).
Fără rețea externă, fără parteneri; doar psql în containerul pg al clonei (docker exec).
Uz: python3 -I tools/teste/t329/sql_loturi.py <container-pg> [<ref git, implicit HEAD>]   → rc 0 dacă fiecare interogare rulează și are
coloanele așteptate; o constantă care nu se poate citi din sursă = NEREZOLVAT (rc 1, X223).
"""
import re
import subprocess
import sys

PG = sys.argv[1]
REF = sys.argv[2] if len(sys.argv) > 2 else "HEAD"
if not PG.startswith("eva-test-p01-t329-"):
    sys.exit("doar containerele eva-test-p01-t329-*")
P = "idempiere/plugins/com.eva.ro.contab/src/com/eva/ro/contab/"


def sursa(rel):
    return subprocess.run(["git", "show", REF + ":" + P + rel], capture_output=True, text=True, check=True).stdout


def literal(expr):
    return "".join(re.findall(r'"((?:[^"\\]|\\.)*)"', expr)).replace('\\"', '"')


def constanta(js, nume):
    m = re.search(r'\b' + re.escape(nume) + r'\s*=\s*(.*?);\s*\n', js, re.S)
    return literal(m.group(1)) if m else None


def nivel0(text, sep=","):
    """Desparte pe separatorul de nivel 0 (în afara literalilor și a parantezelor)."""
    out, cur, ins, adanc = [], "", False, 0
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == "\\" and ins:
            cur += text[i:i + 2]
            i += 2
            continue
        if ch == '"':
            ins = not ins
        elif not ins and ch in "([":
            adanc += 1
        elif not ins and ch in ")]":
            adanc -= 1
        if ch == sep and not ins and adanc == 0:
            out.append(cur)
            cur = ""
        else:
            cur += ch
        i += 1
    if cur.strip():
        out.append(cur)
    return [x.strip() for x in out]


def format_java(cap, args):
    return re.sub(r"%(\d+)\$s", lambda m: args[int(m.group(1)) - 1], cap)

