/**
 * SAGA «Operații → Închidere lună → Înregistrare operații contabile aferente stocurilor»
 * (help p.157): «are rolul de a genera toate notele contabile aferente mișcărilor de stocuri
 * din cadrul gestiunilor cantitativ-valorice».
 *
 * <h3>De ce arată altfel la noi decât la SAGA</h3>
 * În SAGA mișcarea de stoc e o simplă înregistrare, iar nota contabilă 3xx se naște abia la
 * închiderea lunii, în bloc. În iDempiere e invers: fiecare document de stoc (recepție,
 * livrare, bon de consum, inventar, transfer, producție) își face singur nota, la validare,
 * prin motorul de postare — cu {@code CLIENT_ACCOUNTING='I'} chiar în clipa validării. Nu
 * există un al doilea moment în care s-ar mai putea „genera" ceva: ar însemna nota dublă.
 *
 * <p>Ce rămâne, și e chiar util, e cealaltă jumătate a operației: <b>garanția că luna n-a
 * rămas cu documente de stoc nepostate</b>. Un document validat dar nepostat (postare căzută,
 * cont lipsă pe categoria de produs, perioadă închisă la momentul validării) e exact cazul în
 * care închiderea 6xx/7xx ar închide o lună incompletă. Operația le numără, le arată și le
 * postează, una câte una, spunând pe care n-a putut.
 *
 * <p>Din același motiv operația nu produce marcaj propriu și nu se devalidează de aici:
 * notele aparțin documentelor, deci se desfac devalidând documentul, în ecranul lui.
 *
 * <h3>DEFECT REPARAT (08.09) — inventarele importate NU se repostează (P11/P12)</h3>
 * Decizia de fond a importului (P11/P12, «postare fidelă din jurnal») lasă mișcările de stoc
 * importate cu {@code posted='N'} ANUME: contabilitatea lor (371, 607, 4428…) e deja în
 * registru, adusă din nota SAGA a documentului care le-a produs (factura de achiziție la
 * intrare, nota «Închidere» la descărcare). Importul le marchează explicit în
 * {@code Description} cu «NEPOSTAT ANUME…» (v. {@code saga.native/core/CostRepair.java:253},
 * {@code FidelPosting.java:1836}). Pe NEETS, iunie 2026: 119 inventare {@code CO}, toate
 * {@code posted='N'} și toate cu marcajul — iar 371 avea deja rulaj de 19.483,50 lei din notele
 * importate. Fără gardă, «Înregistrare operații contabile aferente stocurilor» le-ar fi postat
 * NATIV (Doc_Inventory), peste contabilitatea din registru: 371 s-ar fi numărat de două ori.
 *
 * <p>De-aceea documentele purtând marcajul {@link #NEPOSTAT_ANUME} NU se numără printre cele
 * «de postat» și NU se postează de aici — sunt înregistrate deja, în altă notă. Un document de
 * stoc nou (de după cutover), nepostat fiindcă i-a căzut postarea, N-ARE marcajul și intră
 * normal în operație.
 */
public final class NoteStocuri {

    /**
     * Marcajul pe care importul îl scrie în {@code Description} pentru o mișcare de stoc lăsată
     * nepostată ANUME (contabilitatea ei e în registru, în nota SAGA a documentului). Un astfel
     * de document nu se repostează — ar dubla stocul. Convenție stabilă a importului, folosită
     * pe toate firmele (CESIRO PRODUCTION, ARIDE IT, RED INTERNET, NEETS…).
     */
    public static final String NEPOSTAT_ANUME = "NEPOSTAT ANUME";

    private NoteStocuri() {
    }

    /**
     * Tabelele de stoc care produc note contabile: numele, eticheta în română și
     * <b>coloana de dată contabilă a fiecăreia</b>.
     *
     * <h3>DEFECT REPARAT (27.08) — coloana a treia nu e decor</h3>
     * Toate cele patru interogări de aici cereau {@code dateacct}. Numai {@code M_InOut}
     * are coloana asta; {@code M_Inventory}, {@code M_Movement} și {@code M_Production}
     * au DOAR {@code movementdate} (verificat în {@code pg_attribute} pe instanță).
     * Interogările pe cele trei tabele cădeau, așadar, cu
     * «column "dateacct" does not exist» — iar căderea era <b>tăcută</b> de două ori:
     * {@link DB#getSQLValue} întoarce −1 la eroare, iar garda {@code if (n != null && n > 0)}
     * din {@link #numara} înghite exact acel −1; în {@link #nepostate}, {@code catch (Exception)}
     * comenta „tabela poate lipsi pe instanță" și trecea mai departe.
     *
     * <p>Efectul, măsurat pe MARIUS / iunie 2026: 11 inventare validate și postate, dar
     * {@link #cateDocumente} întorcea 0, deci operația 1 a închiderii («Înregistrare operații
     * contabile aferente stocurilor») apărea, fals, ca <i>neaplicabilă</i> — o lună cu mișcări
     * de stoc arăta ca o lună fără. Un document de stoc validat dar NEPOSTAT ar fi trecut,
     * din același motiv, complet nevăzut: exact cazul pe care operația există ca să-l prindă.
     *
     * <p>{@code movementdate} e și alegerea motorului de postare — {@code Doc_Inventory},
     * {@code Doc_Movement} și {@code Doc_Production} își iau {@code getDateAcct()} din ea —
     * deci luna numărată aici e aceeași cu luna în care cade nota.
     */
    private static final String[][] TABELE = {
        {"M_InOut", "recepții și livrări", "dateacct"},
        {"M_Inventory", "inventare", "movementdate"},
        {"M_Movement", "transferuri între gestiuni", "movementdate"},
        {"M_Production", "producție / bonuri de consum", "movementdate"},
    };

    /** Câte documente de stoc validate are luna. */
    public static int cateDocumente(int client, YearMonth luna) {
        return numara(client, luna, false);
    }

    /**
     * Câte dintre ele au rămas NEPOSTATE ȘI au nevoie de postare — adică fără cele lăsate
     * nepostate ANUME de import (contabilitatea lor e deja în registru; v. javadoc-ul clasei).
     */
    public static int cateNepostate(int client, YearMonth luna) {
        return numara(client, luna, true);
    }

    /**
     * Câte mișcări de stoc sunt nepostate ANUME (importate, cu contabilitatea în nota SAGA a
     * documentului). Nu se postează de aici — informativ, pentru starea operației 1.
     */
    public static int cateDeliberatNepostate(int client, YearMonth luna) {
        int total = 0;
        for (String[] t : TABELE) {
            Integer n = DB.getSQLValue(null,
                    "SELECT COUNT(*) FROM " + t[0] + " WHERE ad_client_id=?"
                    + " AND docstatus IN ('CO','CL') AND " + t[2] + " BETWEEN ? AND ?"
                    + " AND COALESCE(posted,'N') <> 'Y'"
                    + " AND COALESCE(description,'') LIKE ?",
                    new Object[]{client, InchidereLuna.inceput(luna),
                            InchidereLuna.sfarsit(luna), "%" + NEPOSTAT_ANUME + "%"});
            // T254 eșec închis: semnalat evaluării în curs (InchidereLuna.Verificare) — COUNT(*) reușit nu e niciodată null / negativ
            if (n == null || n < 0) InchidereLuna.Verificare.eroare(new IllegalStateException(t[0]));
            if (n != null && n > 0)
                total += n;
        }
        return total;
    }

    private static int numara(int client, YearMonth luna, boolean doarNepostate) {
        int total = 0;
        for (String[] t : TABELE) {
            // Cele nepostate ANUME (importate) nu se numără printre cele «de postat»: postarea
            // lor nativă ar dubla stocul deja adus din registru — vezi javadoc-ul clasei.
            Object[] par = doarNepostate
                    ? new Object[]{client, InchidereLuna.inceput(luna),
                            InchidereLuna.sfarsit(luna), "%" + NEPOSTAT_ANUME + "%"}
                    : new Object[]{client, InchidereLuna.inceput(luna),
                            InchidereLuna.sfarsit(luna)};
            Integer n = DB.getSQLValue(null,
                    "SELECT COUNT(*) FROM " + t[0] + " WHERE ad_client_id=?"
                    + " AND docstatus IN ('CO','CL') AND " + t[2] + " BETWEEN ? AND ?"
                    + (doarNepostate ? " AND COALESCE(posted,'N') <> 'Y'"
                            + " AND COALESCE(description,'') NOT LIKE ?" : ""),
                    par);
            // T254 eșec închis: semnalat evaluării în curs (InchidereLuna.Verificare) — COUNT(*) reușit nu e niciodată null / negativ
            if (n == null || n < 0) InchidereLuna.Verificare.eroare(new IllegalStateException(t[0]));
            if (n != null && n > 0)
                total += n;
        }
        return total;
    }

    /** Un document de stoc nepostat, pentru previzualizare și pentru postare. */
    public static final class Document {
        public String tabela = "";
        public String eticheta = "";
        public int id;
        public String documentNo = "";
        public Timestamp data;
        public String stare = "";
    }

    /** Documentele de stoc NEPOSTATE ale lunii. */
    public static List<Document> nepostate(int client, YearMonth luna) {
        List<Document> out = new ArrayList<>();
        for (String[] t : TABELE) {
            // Fără cele nepostate ANUME (importate): repostarea lor ar dubla stocul deja adus
            // din registru — vezi javadoc-ul clasei. Ele nu apar nici la previzualizare, nici
            // la postare; un document nou, nepostat din alt motiv, n-are marcajul și intră.
            String sql = "SELECT " + t[0].toLowerCase() + "_id, documentno, " + t[2] + ","
                    + " COALESCE(posted,'N') FROM " + t[0]
                    + " WHERE ad_client_id=? AND docstatus IN ('CO','CL')"
                    + " AND " + t[2] + " BETWEEN ? AND ? AND COALESCE(posted,'N') <> 'Y'"
                    + " AND COALESCE(description,'') NOT LIKE ?"
                    + " ORDER BY " + t[2] + ", documentno";
            try (PreparedStatement ps = DB.prepareStatement(sql, null)) {
                ps.setInt(1, client);
                ps.setTimestamp(2, InchidereLuna.inceput(luna));
                ps.setTimestamp(3, InchidereLuna.sfarsit(luna));
                ps.setString(4, "%" + NEPOSTAT_ANUME + "%");
                try (ResultSet rs = ps.executeQuery()) {
                    while (rs.next()) {
                        Document d = new Document();
                        d.tabela = t[0];
                        d.eticheta = t[1];
                        d.id = rs.getInt(1);
                        d.documentNo = rs.getString(2);
                        d.data = rs.getTimestamp(3);
                        // 'E' = postarea a încercat și a EȘUAT (lecția din motorul Java)
                        d.stare = "E".equals(rs.getString(4)) ? "postare EȘUATĂ" : "nepostat";
                        out.add(d);
                    }
                }
            } catch (Exception e) {
                // T254 eșec închis: semnalat evaluării în curs (InchidereLuna.Verificare)
                com.eva.ro.contab.fiscal.InchidereLuna.Verificare.eroareComponenta(e, t[0]);
                // Tabela poate lipsi pe instanță — trecem la următoarea. ATENȚIE, cititorule:
                // exact liniștea asta a ascuns ani de zile «column "dateacct" does not exist»
                // pe trei tabele din patru (vezi nota de la {@link #TABELE}). Dacă mai adaugi
                // o tabelă aici, verifică-i ÎNTÂI coloana de dată în pg_attribute — o greșeală
                // nu se vede ca eroare, se vede ca o lună fără mișcări de stoc.
            }
        }
        return out;
