    /** DOC_BEFORE_POST: refuză (re)postarea unui document cu mișcări de strat când M_Cost ≠ unitarul înregistrat. */
    public static String laPostare(PO doc) {
        int client = doc.getAD_Client_ID();
        if (client <= 0 || !activ(client))
            return null;
        Map<Integer, BigDecimal> u = unitarePeArticol(miscariDocument(client, doc.get_Table_ID(), doc.get_ID(),
                generatie(client), doc.get_TrxName()));
        if (u.isEmpty())
            return null;
        MAcctSchema as = schema(doc.getCtx(), client);
        int ce = elementCost(client, as, doc.get_TrxName());
        for (Map.Entry<Integer, BigDecimal> e : u.entrySet()) {
            MCost c = MCost.get(MProduct.get(doc.getCtx(), e.getKey()), 0, as, orgCost(as, doc.getAD_Org_ID()), ce,
                    doc.get_TrxName());
            BigDecimal curent = c.getCurrentCostPrice() == null ? BigDecimal.ZERO
                    : c.getCurrentCostPrice().setScale(StraturiCost.SCALA_UNITAR, java.math.RoundingMode.HALF_UP);
            if (curent.compareTo(e.getValue()) != 0)
                return Etichete.t("t40.l2.motor.repostare_refuzata", doc.get_ValueAsString("DocumentNo"));
        }
        return null;
    }

    /** DOC_AFTER_POST: M_Cost ← Σ ValoareRamasa / Σ CantitateRamasa (toate gestiunile, generația curentă), per articol. */
    public static void dupaPostare(PO doc) {
        int client = doc.getAD_Client_ID();
        if (client <= 0 || !activ(client))
            return;
        aplicaAccesoriiInAsteptare(doc);   // P01.T164 L-B (02c_spec_LB.md §3.3.3, D-T164-33): accesoriile DVI amânate, idempotent
        int gen = generatie(client);
        Set<Integer> articole = unitarePeArticol(miscariDocument(client, doc.get_Table_ID(), doc.get_ID(), gen,
                doc.get_TrxName())).keySet();
        if (articole.isEmpty())
            return;
        Map<Integer, BigDecimal> medii = new LinkedHashMap<>();
        for (int pid : articole) {
            BigDecimal[] vq = new BigDecimal[2];
            try (PreparedStatement ps = DB.prepareStatement(sqlMediaRamasa(), doc.get_TrxName())) {
                ps.setInt(1, client);
                ps.setInt(2, pid);
                ps.setInt(3, gen);
                try (ResultSet rs = ps.executeQuery()) {
                    if (rs.next()) {
                        vq[0] = rs.getBigDecimal(1);
                        vq[1] = rs.getBigDecimal(2);
                    }
                }
            } catch (SQLException e) {
                throw new DBException(e, sqlMediaRamasa());
            }
            if (vq[1] != null && vq[1].signum() > 0)
                medii.put(pid, StraturiCost.unitarTransport(vq[0], vq[1]));
        }
        Rulare r = rulare(client, gen, MetodaDescarcare.efectiva(client), doc.get_TrxName(), false);
        scrieCost(doc.getCtx(), r, medii, doc.getAD_Org_ID());
    }

