    /** Postează documentele de stoc rămase nepostate. */
    public static String posteaza(Properties ctx, String trxName, int client, YearMonth luna) {
        // L2-C19 (T40 L2 r2, 01c_3 Q-BE-3): detecția fail-safe a documentelor fără mișcări de strat, în fața rezultatului
        String c19 = avertismentFaraStraturi(client, trxName);
        String rez = posteazaNepostate(ctx, trxName, client, luna);
        return c19 == null ? rez : c19 + " · " + rez;
    }

    private static String posteazaNepostate(Properties ctx, String trxName, int client, YearMonth luna) {
        // T40 L2 r5 (D-B11-1): potrivirile factură–NIR inverse ale unor potriviri EvA cu 0 rânduri, rămase nepostate ⇒ postate (0 rânduri)
        com.eva.ro.contab.fiscal.MotorStraturi.potriviriInverse(client, 0, trxName);
        List<Document> lista = nepostate(client, luna);
        if (lista.isEmpty()) {
            int anume = cateDeliberatNepostate(client, luna);
            if (anume > 0)
                return "n-am ce posta în " + luna + ": cele " + anume + " mișcări de stoc"
                     + " nepostate sunt nepostate ANUME (importate) — contabilitatea lor e deja"
                     + " în registru, în nota SAGA a documentului. Postate aici, stocul s-ar"
                     + " număra de două ori.";
            return "toate documentele de stoc ale lunii " + luna + " sunt deja postate"
                 + " — n-am ce genera (în iDempiere nota 3xx se naște la validarea"
                 + " documentului, nu la închidere)";
        }
        int reusite = 0;
        List<String> esecuri = new ArrayList<>();
        for (Document d : lista) {
            int tableId = MTable.getTable_ID(d.tabela);
            String err;
            try {
                // T40 L2 (02_L2 §A6): firma cu straturi active ⇒ M_Cost ← costul înregistrat al documentului, înaintea postării
                if (com.eva.ro.contab.fiscal.MotorStraturi.activ(client))
                    com.eva.ro.contab.fiscal.MotorStraturi.pregatestePostare(d.tabela, d.id, trxName);
                err = DocumentEngine.postImmediate(ctx, client, tableId, d.id, true, trxName);
            } catch (RuntimeException ex) {
                err = ex.getMessage();
            }
            if (err == null || err.isEmpty())
                reusite++;
            else if (esecuri.size() < 15)
                esecuri.add(d.documentNo + " (" + d.eticheta + "): " + err);
        }
        return reusite + " din " + lista.size() + " documente de stoc postate"
                + (esecuri.isEmpty() ? ""
                   : " · AU RĂMAS: " + String.join(" · ", esecuri));
    }

