    static Map<Integer, BigDecimal> unitarePeArticol(List<Object[]> miscari) {
        Map<Integer, BigDecimal[]> acc = new TreeMap<>();
        for (Object[] m : miscari) {
            BigDecimal q = (BigDecimal) m[1], v = (BigDecimal) m[2];
            BigDecimal[] a = acc.computeIfAbsent((Integer) m[0], k -> new BigDecimal[]{BigDecimal.ZERO, BigDecimal.ZERO,
                    BigDecimal.ZERO, BigDecimal.ZERO});
            int k = q.signum() < 0 ? 0 : 2;
            a[k] = a[k].add(q.abs());
            a[k + 1] = a[k + 1].add(v.abs());
        }
        Map<Integer, BigDecimal> out = new TreeMap<>();
        for (Map.Entry<Integer, BigDecimal[]> e : acc.entrySet()) {
            BigDecimal[] a = e.getValue();
            if (a[0].signum() > 0)
                out.put(e.getKey(), StraturiCost.unitarTransport(a[1], a[0]));
            else if (a[2].signum() > 0)
                out.put(e.getKey(), StraturiCost.unitarTransport(a[3], a[2]));
        }
        return out;
    }

