/**
 * P01.T163 (D-ORC-T163-27) — postarea documentului de inventar fizic, identică cu {@code Doc_Inventory} pe liniile cu diferență ≠ 0
 * (371 / 7588 la plus, 607 / 371 la minus), care SARE liniile fără diferență ({@link ReguliPostareInventar#sePosteaza}). Documentul
 * nu se schimbă: liniile rămân active și apar în PV D1005, în grilă și în stornare; doar lista de linii a NOTEI le exclude. Stornarea
 * («Devalidez») e tot un M_Inventory, deci perechea trece prin aceeași clasă și același filtru (CO-1).
 */
public class DocInventarEva extends Doc_Inventory {

    public DocInventarEva(MAcctSchema as, ResultSet rs, String trxName) {
        super(as, rs, trxName);
    }

    @Override
    protected String loadDocumentDetails() {
        String r = super.loadDocumentDetails();
        if (p_lines != null) {
            List<DocLine> pastrate = new ArrayList<>();
            for (DocLine l : p_lines)
                if (ReguliPostareInventar.sePosteaza(l.getQty(), l.getAmtSource()))
                    pastrate.add(l);
            p_lines = pastrate.toArray(new DocLine[0]);
        }
        return r;
    }
}

