        }
    }

    /** Cheia lacătului: {@code 0x155 << 48 | tabelă << 32 | înregistrare}. */
    static long cheieLacat(int tableId, int recordId) {
        return (0x155L << 48) | ((long) tableId << 32) | (recordId & 0xFFFFFFFFL);
    }

    /** O pereche citită din parametru: {@code eroare != null} = pereche malformată (refuz pe rând, cu cheie). */
    static final class Pereche {
        final int tableId, recordId;
        final String text, eroare;

        Pereche(int tableId, int recordId, String text, String eroare) {
            this.tableId = tableId;
            this.recordId = recordId;
            this.text = text;
            this.eroare = eroare;
        }
    }

    /**
     * Citirea pură a parametrului: {@code null} = peste {@value #MAX_PERECHI} perechi (refuzul întregii cereri);
     * altfel lista perechilor, cele malformate cu cheia de refuz.
     */
    static java.util.List<Pereche> citeste(String valoare) {
        java.util.List<Pereche> out = new java.util.ArrayList<>();
        if (valoare == null || valoare.isBlank())
            return out;
        String[] bucati = valoare.split(",", -1);
        if (bucati.length > MAX_PERECHI)
            return null;
        for (String b : bucati) {
            String s = b.trim();
            java.util.regex.Matcher m = java.util.regex.Pattern.compile("([0-9]{1,9}):([0-9]{1,9})").matcher(s);
            if (m.matches()) {
                int t = Integer.parseInt(m.group(1)), r = Integer.parseInt(m.group(2));
                out.add(r > 0 && t > 0 ? new Pereche(t, r, s, null) : new Pereche(0, 0, s, "t155.nep.refuz.format"));
            } else {
                out.add(new Pereche(0, 0, s, "t155.nep.refuz.format"));
            }
        }
        return out;
    }

    @Override
    protected String doIt() throws Exception {
        int client = getAD_Client_ID();
        java.util.List<Pereche> perechi = citeste(inregistrari);
        if (perechi == null)
            return Etichete.t("t155.nep.refuz.peste_200", String.valueOf(MAX_PERECHI));
        int reusite = 0, esuate = 0, refuzate = 0;
        for (Pereche p : perechi) {
